using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Reflection;
internal static class CompanionEnhancementTests {
 internal static void Run(string folder){var store=new Store(Path.Combine(folder,"completion-tests"));var c=new DofusCharacter{id="complete-a",name="A",guide="parcours-exemple"};store.Value.dofus.characters.Add(c);store.Value.dofus.active=c.id;TougliReader.Cache(store,c.guide,StandaloneTests.Sample);var doc=QuestProgress.Read(store,c,c.guide);var p=DofusCompanion.Get(store.Value,c);p.done.AddRange(doc.Steps.Select(s=>s.Key));p.done.Add("obsolete-key");if(!GuideCompletion.IsComplete(store,c,c.guide))throw new Exception("Completion ignores obsolete keys");var other=new DofusCharacter{id="complete-b",name="B",guide=c.guide};if(GuideCompletion.IsComplete(store,other,c.guide)||GuideCompletion.IsComplete(store,c,"missing-guide"))throw new Exception("Completion leaked or missing cache completed");p.done.Clear();if(GuideCompletion.IsComplete(store,c,c.guide))throw new Exception("Undo completion failed");string archive=Path.Combine(folder,"companion-update-test.zip");using(var zip=ZipFile.Open(archive,ZipArchiveMode.Create)){foreach(string name in CompanionUpdateDownload.Required)zip.CreateEntryFromFile(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name),name);}var version=Assembly.GetExecutingAssembly().GetName().Version;string target=CompanionUpdateDownload.Stage(archive,Path.Combine(folder,"staged-companion"),version);if(!File.Exists(target))throw new Exception("Update not staged");bool rejected=false;try{CompanionUpdateDownload.Stage(archive,Path.Combine(folder,"wrong-companion"),new Version(99,0,0,0));}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Wrong version accepted");File.WriteAllText(Path.Combine(folder,"COMPANION_ENHANCEMENTS_PASS.txt"),"PASS: per-character exact completion, obsolete keys, missing cache, undo, complete package staging and wrong-version rejection.");}
}
